static int _max;

static void UpdateMax(int candidate)
{
    int current = Volatile.Read(ref _max);
    while (candidate > current)
    {
        int seen = Interlocked.CompareExchange(ref _max, candidate, current);
        if (seen == current) return;   // made it
        current = seen;                // beaten: take the fresh value and retry
    }
}
